mapper.select:
select

from pro_feedback

    del_flag = '0'
    and workorder_id = #{workorderId}

        and workorder_code like concat('%', #{workorderCode}, '%')

    and task_id = #{taskId}

        and task_code like concat('%', #{taskCode}, '%')


        and feedback_code like concat('%', #{feedbackCode}, '%')

    and process_id = #{processId}
    and workstation_id = #{workstationId}
    and feedback_type = #{feedbackType}
    and feedback_channel = #{feedbackChannel}
    and status = #{status}
    and feedback_time >= #{feedbackTime}

order by feedback_time desc, record_id desc

mapper.update:
update pro_feedback
set feedback_code = #{feedbackCode}
where record_id = #{id}
